+                vec![
+                    Triangle::new(t.a, t.b, center),
+                    Triangle::new(t.b, t.c, center),
+                    Triangle::new(t.c, t.a, center),
+                ]
+            } else {
+                vec![t]
+            }
+        })
+        .collect()
